package com.google.gson;import java.util.*;public class JsonObject extends JsonElement {Map<String,JsonElement> map=new HashMap<>();public JsonObject(){super(null);}public boolean has(String key){return map.containsKey(key);}public JsonElement get(String key){return map.get(key);}public JsonObject getAsJsonObject(String key){JsonElement e=map.get(key);return e instanceof JsonObject?(JsonObject)e:null;}public void add(String k,JsonElement v){map.put(k,v);}}
